def rects(g, col=8):
    seen=set(); out=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]==col and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c)); cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<len(g) and 0<=nx<len(g[0]) and g[ny][nx]==col and (ny,nx) not in seen:
                            seen.add((ny,nx)); stack.append((ny,nx))
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                out.append((min(rs),min(cs),max(rs),max(cs)))
    return out

def key_cells(g):
    return [(r,c,g[r][c]) for r in range(len(g)) for c in range(len(g[0])) if g[r][c] not in (0,8)]

def rot_cw(cells):  # rotate 90 CW about bbox
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    H=max(rs)-min(rs)+1
    return [(c, H-1-(r-min(rs))) for r,c in cells]

def solve(g):
    R=rects(g); K=key_cells(g)
    # cluster key by color
    from collections import defaultdict
    cl=defaultdict(list)
    for r,c,v in K: cl[v].append((r,c))
    for s in range(1,9):
        # downsampled shapes of rects, normalized
        rshapes={}
        for (r0,c0,r1,c1) in R:
            h=(r1-r0+1); w=(c1-c0+1)
            if h%s or w%s: break
            cells=frozenset((i//s,j//s) for i in range(h) for j in range(w))
            mr=min(a for a,b in cells); mc=min(b for a,b in cells)
            rshapes[(r0,c0)]=frozenset((a-mr,b-mc) for a,b in cells)
        else:
            kshapes={}
            for v,cells in cl.items():
                rc=rot_cw(cells)
                mr=min(a for a,b in rc); mc=min(b for a,b in rc)
                kshapes[v]=frozenset((a-mr,b-mc) for a,b in rc)
            assign={}
            ok=True
            for pos,sh in rshapes.items():
                cands=[v for v,ks in kshapes.items() if ks==sh]
                if len(cands)!=1: ok=False; break
                assign[pos]=cands[0]
            if ok and len(assign)==len(rshapes):
                return R, assign, s
    return None

