def rot_cw_abs(cells):
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
    # CW: (r,c) -> (c, r1 - r) ; then shift to origin
    pts=[(c-c0, r1-r) for r,c in cells]
    mr=min(a for a,b in pts); mc=min(b for a,b in pts)
    return [(a-mr,b-mc) for a,b in pts]

