def rect_decomp_backtrack(g, col=8):
    H,W=len(g),len(g[0])
    def segs(cov):
        res={}
        for r in range(H):
            out=[];c=0
            while c<W:
                if g[r][c]==col and not cov[r][c]:
                    c0=c
                    while c<W and g[r][c]==col and not cov[r][c]: c+=1
                    out.append((c0,c-1))
                else: c+=1
            res[r]=out
        return res
    def cands(cov):
        out=[]
        for r,ss in segs(cov).items():
            for (a,b) in ss:
                r2=r
                while r2+1<H and any(x<=a and b<=y for x,y in segs(cov)[r2+1]): r2+=1
                out.append((r,a,r2,b))
        # dedupe
        return sorted(set(out), key=lambda t:-((t[2]-t[0]+1)*(t[3]-t[1]+1)))
    results=[]
    def rec(cov, acc):
        if all(not (g[r][c]==col and not cov[r][c]) for r in range(H) for c in range(W)):
            results.append(list(acc)); return True
        for (r,a,r2,b) in cands(cov):
            nc=[row[:] for row in cov]
            for rr in range(r,r2+1):
                for cc in range(a,b+1): nc[rr][cc]=True
            acc.append((r,a,r2,b))
            if rec(nc,acc): return True
            acc.pop()
        return False
    rec([[False]*W for _ in range(H)],[])
    return results

