            for i in range(s):
                for j in range(s): grid[(a*s+i,b*s+j)]=v
        cov=[[False]*W for _ in range(H)]
        assign={}
        def first_unc():
            for r in range(H):
                for c in range(W):
                    if g[r][c]==col and not cov[r][c]: return r,c
            return None
        def rec():
            fu=first_unc()
            if fu is None: return dict(assign)
            r0,c0=fu
            # rectangle must start at (r0,c0); extend down/right
            maxr=r0
            while maxr+1<H and g[maxr+1][c0]==col and not cov[maxr+1][c0]: maxr+=1
            for r2 in range(r0,maxr+1):
                maxc=c0
                while maxc+1<W and all(g[rr][maxc+1]==col and not cov[rr][maxc+1] for rr in range(r0,r2+1)): maxc+=1
                for c2 in range(c0,maxc+1):
