                    gs=set()
                    ok=True
                    for rr in range(r0,r2+1):
                        for cc in range(c0,c2+1):
                            if cov[rr][cc] or (rr,cc) not in grid: ok=False; break
                            gs.add(grid[(rr,cc)])
                        if not ok: break
                    if not ok or len(gs)!=1: continue
                    for rr in range(r0,r2+1):
                        for cc in range(c0,c2+1): cov[rr][cc]=True
                    assign[(r0,c0,r2,c2)]=gs.pop()
                    res=rec()
                    if res is not None: return res
                    for rr in range(r0,r2+1):
                        for cc in range(c0,c2+1): cov[rr][cc]=False
                    del assign[(r0,c0,r2,c2)]
            return None
